Content.Example:
@model Student //معرفی مدل ورودی به صفحه

@{
    ViewData["Title"] = "Get Student";
    Layout = "~/Views/Shared/_Layout.cshtml;
}

//در دسترس است Model دیتای ورودی به ویو همیشه از طریق
<h1>@Model.Name @Model.Family</h1>
<h3>@Model.Age</h3>

public class HomeController : Controller
{
    public IActionResult GetStudents()
   {
      var data=new List<Student>{
          new Student{ Name = "amir", Family = "asadi", Age = 17 },
          new Student{ Name = "sara", Family = "ahmadi", Age = 19 },
          new Student{ Name = "arad", Family = "amiri", Age = 15 }
         };
      return View(data);
   }
}

@model List<Student> //معرفی مدل ورودی به صفحه

@{
    ViewData["Title"] = "Get Students List";
    Layout = "~/Views/Shared/_Layout.cshtml;
}

//در دسترس است Model دیتای ورودی به ویو همیشه از طریق
@foreach(var item in Model)
{
    <h1>@item.Name @item.Family</h1>
    <h3>@item.Age</h3>
}

Content.Description:
//مدل ها، کلیدهای اصلی و خارجی
//+Validation Rules : اعتبارسنجی ورودی های هر فیلد

//Product.cs : مدل محصول
//ارتباط 'یک به چند' روی مدل های محصول و دسته بندی

Content.Example:
using System.ComponentModel.DataAnnotations; //key
using System.ComponentModel.DataAnnotations.Schema; //ForeignKey

public class Product
{
    [Display(Name = "شماره محصول")]
    [Key] //auto number کلید اصلی از نوع
    public int Id {get; set;}

    [Display(Name = "عنوان",Prompt = "نام محصول")]
    [Required(ErrorMessage = "فیلد الزامی")]
    public string Title {get; set;}

    [Display(Name = "درباره محصول",Prompt = "توضیحات")]
    //بودن nullable علامت سوال انتهای نوع داده به معنی
    public string? Description {get; set;}

    public string? Img {get; set;}

    [Display(Name = "قیمت")]
    //ثبت مقدار پیش فرض برای فیلد
    public int Price {get; set;} = 0;

    [Display(Name = "تعداد موجودی")]
    public int Inventory {get; set;} = 0;

    public int CategoryId {get; set;}

    //ForeignKey on navigation
    //product -> category -> 1
    [ForeignKey(nameof(CategoryId))]
    public Category Category {get; set;}
}

using System.ComponentModel.DataAnnotations; //key
using System.ComponentModel.DataAnnotations.Schema; //DatabaseGeneratedOption

public class Group
{
    [Key] //کلید اصلی غیر خودکار
    [DatabaseGenerated(DatabaseGeneratedOption.None)]
    public int Id {get; set;}

    [Display(Name = "عنوان",Prompt = "نام دسته بندی")]
    public string Title {get; set;}

    //category -> product -> n
    public ICollection<Product> Products {get; set;} = new List<Product>();
}

