//DatabaseContext.cs فایل
//دفترچه راهنمای ارتباط سایت یا برنامه شما با دیتابیس اصلی

/*
using Microsoft.EntityFrameworkCore;

public class AppDbContext : DbContext
{

database tables base on models
public DbSet<[modelName]> [tableName] => Set<[modelName]>();
-----------------------------------------------------------------
database type, address, name, ...
1: public AppDbContext... -> confige in Program.cs

or

2: protected override void OnConfiguring...
-----------------------------------------------------------------
default values on table creating time
protected override void OnModelCreating...

}
*/

Content.Example:
using Microsoft.EntityFrameworkCore;

public class AppDbContext : DbContext
{

// database tables base on models
    //public DbSet<[modelName]> [tableName] => { get; set; }
    //public DbSet<[modelName]> [tableName] => Set<[modelName]>();

    public DbSet<Product> Products => Set<Product>();
    public DbSet<Category> Categories => Set<Category>();

// database type, address, name, ...
    //1
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options)
    {

       //confige in Program.cs
    }

    //2
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        //sqlite
        optionsBuilder.UseSqlite("Data Source=myData.db");

        //sql server
        //optionsBuilder.UseSqlServer("...");
}


// default values on table creating time
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
       base.OnModelCreating(modelBuilder);

       var categories = new List<Category>
       {
          new(){Id = 1, Title = "پوشاک"},
          new(){Id = 2, Title = "لوازم خانگی"},
          new(){Id = 3, Title = "صنایع دستی"},
       };

       modelBuilder.Entity<Category>().HasData(categories);
       }}

