Content.Example:
@model Student

@{
    ViewData["Title"] = "Get Student";
    Layout = "~/Views/Shared/_Layout.cshtml;
}

<form asp-controller="home" asp-action="submitStudent" method="post">
    <input asp-for="Name"/>
    <input asp-for="Family"/>
    <input asp-for="Age"/>
    <button>send</button>
</form>

public async Task<IActionResult> Create()
{
    return View();
}

[httpPost]//الزامی
public async Task<IActionResult> Create(Category data)
{

    //بررسی اعتبارسنجی های تعریف شده روی مدل ورودی
    if (ModelState.IsValid)
    {
       //ثبت دسته بندی
       _db.Categories.Add(data)

       //ذخیره تغییرات _ مهم پلاس
       _db.SaveChanged()

       //بازگشت به صفحه نمایش دسته بندی ها
       return RedirectToAction(nameof(Index)); 
    }

    //بازگشت به صفحه ثبت
    return View(data);
}
